uint32_t simple_case_fold(uint32_t code_point) {
	size_t lo = 0, hi = sizeof(kFoldRuns) / sizeof(kFoldRuns[0]);
	while (lo < hi) {
		const size_t mid = lo + (hi - lo) / 2;
		if (kFoldRuns[mid].first <= code_point) lo = mid + 1;
		else hi = mid;
	}
	if (lo == 0) return code_point;
	const FoldRun &run = kFoldRuns[lo - 1];
	if (code_point > run.last || (code_point - run.first) % run.stride != 0) return code_point;
	return static_cast<uint32_t>(static_cast<int64_t>(code_point) + run.delta);
}

